<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');if(!in_array($role,['admin','director','sub_director','headteacher','bursar'],true)){http_response_code(403);exit('Your role cannot view fee receipts.');}$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$entryId=filter_var($_GET['entry_id']??null,FILTER_VALIDATE_INT);if(!$school||!$entryId){http_response_code(422);exit('Choose a fee receipt.');}$db=db();$q=$db->prepare('SELECT s.name school_name,p.id pupil_id,p.admission_number,p.first_name,p.middle_name,p.last_name,p.class_level,p.stream,l.id,l.academic_year,l.term,l.description,l.amount,l.payment_method,l.reference,l.created_at,l.recorded_by,u.name recorder FROM schools s JOIN school_memberships m ON m.school_id=s.id AND m.user_id=? JOIN school_fee_ledger l ON l.school_id=s.id AND l.id=? AND l.entry_type=\'payment\' JOIN pupils p ON p.id=l.pupil_id AND p.school_id=s.id JOIN users u ON u.id=l.recorded_by WHERE s.id=?');$q->execute([$uid,$entryId,$school]);$receipt=$q->fetch();if(!$receipt){http_response_code(404);exit('Payment receipt not found in an accessible school.');}$q=$db->prepare("SELECT id,reversal_reason,created_at FROM school_fee_ledger WHERE school_id=? AND pupil_id=? AND reversal_of=? AND entry_type='payment_reversal'");$q->execute([$school,$receipt['pupil_id'],$entryId]);$reversal=$q->fetch();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment receipt · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><style>.receipt{max-width:760px;margin:auto}.receipt-number{font:700 14px ui-monospace,monospace}.receipt-table th{width:34%}@media print{.sidebar,.topbar,.screen-only,.page-footer{display:none!important}.main-area{margin:0!important;padding:0!important}.page-content{max-width:none!important;padding:20px!important}.receipt{box-shadow:none!important;border:0!important}.table-wrap{overflow:visible!important}table{min-width:0!important}}</style></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><div class="crumb">School fees <span>/</span> Payment receipt</div><button class="button primary screen-only" type="button" onclick="window.print()">Print / Save PDF</button></header><div class="page-content"><section class="content-section receipt"><div class="section-heading"><div><div class="eyebrow">SCHOOL FEE PAYMENT</div><h1>Payment receipt</h1><p class="muted"><?=e($receipt['school_name'])?></p></div><div class="receipt-number">System reference<br>SLR-<?=$school?>-<?=$entryId?></div></div><?php if($reversal):?><div class="notice error" role="status"><strong>Reversed payment.</strong> Reversal recorded <?=e(date('j M Y H:i',strtotime($reversal['created_at'])))?>. Reason: <?=e($reversal['reversal_reason']?:'—')?></div><?php endif;?><div class="table-wrap"><table class="receipt-table"><tbody><tr><th>Received from</th><td><?=e(trim($receipt['first_name'].' '.($receipt['middle_name']??'').' '.$receipt['last_name']))?></td></tr><tr><th>Admission number</th><td><?=e($receipt['admission_number'])?></td></tr><tr><th>Class / stream</th><td><?=e($receipt['class_level'].($receipt['stream']?' · '.$receipt['stream']:''))?></td></tr><tr><th>Amount paid</th><td><strong>KES <?=number_format((float)$receipt['amount'],2)?></strong></td></tr><tr><th>Payment method</th><td><?=e($receipt['payment_method']?:'—')?></td></tr><tr><th>Receipt / payment reference</th><td><?=e($receipt['reference']?:'—')?></td></tr><tr><th>For</th><td><?=e($receipt['description'])?> · <?=e($receipt['academic_year'].' · '.$receipt['term'])?></td></tr><tr><th>Received on</th><td><?=e(date('j M Y H:i',strtotime($receipt['created_at'])))?></td></tr><tr><th>Recorded by</th><td><?=e($receipt['recorder'])?></td></tr></tbody></table></div><p class="muted">This receipt reflects the school fee ledger at the time of recording. A reversed payment remains visible here with its reversal status.</p><a class="button screen-only" href="accounting.php?school_id=<?=$school?>&amp;pupil_id=<?=$receipt['pupil_id']?>">Back to pupil account</a></section></div></main></div></body></html>